INSERT INTO public.authors(id,slug,name_kn,role_kn,bio_kn,credentials_kn,photo_url,is_active) VALUES('2a15a157-43ad-4781-8d30-aecb31ac65e8','jwalamala-desk','ಜ್ವಾಲಾಮಾಲ ಸಂಪಾದಕೀಯ ತಂಡ','ಸಂಪಾದಕೀಯ ತಂಡ — ಮಾದರಿ','ಮಾದರಿ ಮಾಹಿತಿ — ಪ್ರಕಟಣೆಗೆ ಮೊದಲು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆ ಅಗತ್ಯ.','ಲೇಖಕರ ವಿವರಗಳು ಪರಿಶೀಲನೆಯಲ್ಲಿವೆ.',null,true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001000','seed-shravanabelagola-heritage','ಶ್ರವಣಬೆಳಗೊಳ: ಭಕ್ತಿ, ಪರಂಪರೆ ಮತ್ತು ಇತಿಹಾಸದ ಜೀವಂತ ಸಂಗಮ','Shravanabelagola: a living heritage','shravanabelagola shravana belagola bahubali','ಬೆಟ್ಟದ ಮೇಲಿನ ಬಾಹುಬಲಿಯ ಸನ್ನಿಧಿಯಿಂದ ಬಸದಿಗಳ ಶಿಲ್ಪಕಲೆಯವರೆಗೆ — ನಮ್ಮ ಜೈನ ಪರಂಪರೆಯನ್ನು ಹತ್ತಿರದಿಂದ ಪರಿಚಯಿಸಿಕೊಳ್ಳೋಣ.','<p>ಬೆಟ್ಟದ ಮೇಲಿನ ಬಾಹುಬಲಿಯ ಸನ್ನಿಧಿಯಿಂದ ಬಸದಿಗಳ ಶಿಲ್ಪಕಲೆಯವರೆಗೆ — ನಮ್ಮ ಜೈನ ಪರಂಪರೆಯನ್ನು ಹತ್ತಿರದಿಂದ ಪರಿಚಯಿಸಿಕೊಳ್ಳೋಣ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-14','2026-09-16T06:30:00Z','ಶ್ರವಣಬೆಳಗೊಳ','/images/hill.webp',null,null,'none',true,true,false,null,1200,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','ef0cd62b-fb5a-467e-8172-78f87985104a') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001001','seed-moodbidri-basadi','ಮೂಡುಬಿದಿರೆಯ ಸಾವಿರ ಕಂಬದ ಬಸದಿಯ ಕಲಾ ವೈಭವ','Moodbidri thousand pillar basadi','moodbidri basadi heritage','ಶತಮಾನಗಳ ಶಿಲ್ಪಕಲೆ, ಸಾಂಸ್ಕೃತಿಕ ಸ್ಮೃತಿ ಮತ್ತು ಜೈನ ಪರಂಪರೆಯ ಸುಂದರ ಪರಿಚಯ.','<p>ಶತಮಾನಗಳ ಶಿಲ್ಪಕಲೆ, ಸಾಂಸ್ಕೃತಿಕ ಸ್ಮೃತಿ ಮತ್ತು ಜೈನ ಪರಂಪರೆಯ ಸುಂದರ ಪರಿಚಯ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-14','2026-09-16T06:30:00Z','ಮೂಡುಬಿದಿರೆ','/images/temple.webp',null,null,'none',false,false,false,null,1161,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','3fcfc94f-1294-4d73-8472-0b246ef587c8') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001002','seed-chaturmasa-reflections','ಚಾತುರ್ಮಾಸ: ಆತ್ಮಚಿಂತನೆ ಮತ್ತು ಅಹಿಂಸೆಯ ಹಾದಿಯಲ್ಲಿ','Chaturmasa reflections on ahimsa','chaturmasa ahimsa pravachana','ನಿತ್ಯ ಜೀವನದಲ್ಲಿ ಸಂಯಮ, ಕರುಣೆ ಮತ್ತು ಸರಳತೆಯ ಮಹತ್ವವನ್ನು ತಿಳಿಸುವ ಚಿಂತನೆಗಳು.','<p>ನಿತ್ಯ ಜೀವನದಲ್ಲಿ ಸಂಯಮ, ಕರುಣೆ ಮತ್ತು ಸರಳತೆಯ ಮಹತ್ವವನ್ನು ತಿಳಿಸುವ ಚಿಂತನೆಗಳು.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','video','published','2026-09-13','2026-09-16T06:30:00Z','ಹಾಸನ','/images/detail.webp',null,null,'none',false,false,false,null,1122,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','384ca3a5-2312-4d39-871b-09e69a7bc51b') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001003','seed-youth-community','ಸಮಾಜದ ಸೇವೆಯಲ್ಲಿ ಯುವಜನರ ಪಾತ್ರ: ಹೊಸ ಹೆಜ್ಜೆಗಳು','Youth and community service','samaja youth community seva','ಶಿಕ್ಷಣ, ಪರಿಸರ ಮತ್ತು ಸಮಾಜಸೇವೆಯಲ್ಲಿ ಯುವಜನರ ಭಾಗವಹಿಸುವಿಕೆಗೆ ಒಂದು ವೇದಿಕೆ.','<p>ಶಿಕ್ಷಣ, ಪರಿಸರ ಮತ್ತು ಸಮಾಜಸೇವೆಯಲ್ಲಿ ಯುವಜನರ ಭಾಗವಹಿಸುವಿಕೆಗೆ ಒಂದು ವೇದಿಕೆ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-13','2026-09-15T06:30:00Z','ಬೆಂಗಳೂರು','/images/landscape.webp',null,null,'none',false,false,false,null,1083,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','7cf4f1d9-b7ae-44d1-8eef-13c09299c523') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001004','seed-panchakalyana-tradition','ಪಂಚಕಲ್ಯಾಣ ಮಹೋತ್ಸವದ ಆಚರಣೆಗಳು ಮತ್ತು ಮಹತ್ವ','Understanding Panchakalyana','panchakalyana utsava tradition','ಪಂಚಕಲ್ಯಾಣದ ಐದು ಮಂಗಳ ಸಂದರ್ಭಗಳ ಅರ್ಥ ಮತ್ತು ಅವು ನೀಡುವ ಜೀವನ ಸಂದೇಶ.','<p>ಪಂಚಕಲ್ಯಾಣದ ಐದು ಮಂಗಳ ಸಂದರ್ಭಗಳ ಅರ್ಥ ಮತ್ತು ಅವು ನೀಡುವ ಜೀವನ ಸಂದೇಶ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','video','published','2026-09-12','2026-09-15T06:30:00Z','ಮೈಸೂರು','/images/temple.webp',null,null,'none',false,false,false,null,1044,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','a076bcef-aece-4905-8ba0-8c9935802acc') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001005','seed-jain-education','ವಿದ್ಯೆಯ ಬೆಳಕು: ವಿದ್ಯಾರ್ಥಿಗಳ ಸಾಧನೆಗೆ ಸಮಾಜದ ಬೆಂಬಲ','Education and community support','education vidya students samaja','ಸಮುದಾಯದ ಸಹಕಾರದಿಂದ ಕಲಿಕೆಯ ಅವಕಾಶಗಳನ್ನು ವಿಸ್ತರಿಸುವ ವಿಚಾರಗಳ ಪರಿಚಯ.','<p>ಸಮುದಾಯದ ಸಹಕಾರದಿಂದ ಕಲಿಕೆಯ ಅವಕಾಶಗಳನ್ನು ವಿಸ್ತರಿಸುವ ವಿಚಾರಗಳ ಪರಿಚಯ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-12','2026-09-15T06:30:00Z','ತುಮಕೂರು','/images/detail.webp',null,null,'none',false,false,false,null,1005,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','55fa6667-333a-4301-83db-0d49a930a3b3') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001006','seed-dharmasthala-journey','ಧರ್ಮಸ್ಥಳದತ್ತ ಒಂದು ಸಾಂಸ್ಕೃತಿಕ ಪಯಣ','A cultural journey to Dharmasthala','dharmasthala heritage journey','ನಂಬಿಕೆ, ಸೇವೆ ಮತ್ತು ಸಹಬಾಳ್ವೆಯ ಪರಂಪರೆಯನ್ನು ಅರಿಯುವ ಒಂದು ಪಯಣ.','<p>ನಂಬಿಕೆ, ಸೇವೆ ಮತ್ತು ಸಹಬಾಳ್ವೆಯ ಪರಂಪರೆಯನ್ನು ಅರಿಯುವ ಒಂದು ಪಯಣ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','video','published','2026-09-11','2026-09-14T06:30:00Z','ಧರ್ಮಸ್ಥಳ','/images/landscape.webp',null,null,'none',false,false,false,null,966,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','0c83bae0-2a21-42be-869c-0a49154d43c1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001007','seed-ahimsa-daily','ದಿನನಿತ್ಯದ ಬದುಕಿನಲ್ಲಿ ಅಹಿಂಸೆ: ಸಣ್ಣ ಬದಲಾವಣೆ, ದೊಡ್ಡ ಅರ್ಥ','Ahimsa in everyday life','ahimsa jain pravachana','ಮಾತು, ಮನಸ್ಸು ಮತ್ತು ನಡೆಗಳಲ್ಲಿ ಕರುಣೆಯ ದಾರಿಯನ್ನು ಅನುಸರಿಸುವ ಸರಳ ಮಾರ್ಗಗಳು.','<p>ಮಾತು, ಮನಸ್ಸು ಮತ್ತು ನಡೆಗಳಲ್ಲಿ ಕರುಣೆಯ ದಾರಿಯನ್ನು ಅನುಸರಿಸುವ ಸರಳ ಮಾರ್ಗಗಳು.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-11','2026-09-14T06:30:00Z','ಶ್ರವಣಬೆಳಗೊಳ','/images/hill.webp',null,null,'none',false,false,false,null,927,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','ef0cd62b-fb5a-467e-8172-78f87985104a') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001008','seed-basadi-conservation','ನಮ್ಮ ಬಸದಿಗಳ ಸಂರಕ್ಷಣೆ: ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಪರಂಪರೆ','Preserving our basadis','basadi preservation heritage','ಐತಿಹಾಸಿಕ ಸ್ಮಾರಕಗಳ ಸಂರಕ್ಷಣೆಯಲ್ಲಿ ಸ್ಥಳೀಯ ಸಮುದಾಯದ ಜವಾಬ್ದಾರಿ.','<p>ಐತಿಹಾಸಿಕ ಸ್ಮಾರಕಗಳ ಸಂರಕ್ಷಣೆಯಲ್ಲಿ ಸ್ಥಳೀಯ ಸಮುದಾಯದ ಜವಾಬ್ದಾರಿ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-10','2026-09-14T06:30:00Z','ಕಾರ್ಕಳ','/images/temple.webp',null,null,'none',false,false,false,null,888,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','bf02b30e-005a-4014-8d7c-e1315afc0e4d') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001009','seed-festival-community','ಉತ್ಸವಗಳು ಬೆಸೆಯುವ ಸಮುದಾಯದ ಬಾಂಧವ್ಯ','Festivals bring us together','utsava samaja community festival','ಸಂಪ್ರದಾಯ ಮತ್ತು ಒಗ್ಗಟ್ಟಿನ ಆಚರಣೆಗಳ ಮೂಲಕ ಸಮುದಾಯದಲ್ಲಿ ಮೂಡುವ ಆತ್ಮೀಯತೆ.','<p>ಸಂಪ್ರದಾಯ ಮತ್ತು ಒಗ್ಗಟ್ಟಿನ ಆಚರಣೆಗಳ ಮೂಲಕ ಸಮುದಾಯದಲ್ಲಿ ಮೂಡುವ ಆತ್ಮೀಯತೆ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','video','published','2026-09-10','2026-09-13T06:30:00Z','ಬೆಳಗಾವಿ','/images/detail.webp',null,null,'none',false,false,false,null,849,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','8e420b12-4b76-4403-8ee5-6991a8cbeb74') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001010','seed-shravanabelagola-heritage-archive','ಶ್ರವಣಬೆಳಗೊಳ: ಭಕ್ತಿ, ಪರಂಪರೆ ಮತ್ತು ಇತಿಹಾಸದ ಜೀವಂತ ಸಂಗಮ','Shravanabelagola: a living heritage','shravanabelagola shravana belagola bahubali','ಬೆಟ್ಟದ ಮೇಲಿನ ಬಾಹುಬಲಿಯ ಸನ್ನಿಧಿಯಿಂದ ಬಸದಿಗಳ ಶಿಲ್ಪಕಲೆಯವರೆಗೆ — ನಮ್ಮ ಜೈನ ಪರಂಪರೆಯನ್ನು ಹತ್ತಿರದಿಂದ ಪರಿಚಯಿಸಿಕೊಳ್ಳೋಣ.','<p>ಬೆಟ್ಟದ ಮೇಲಿನ ಬಾಹುಬಲಿಯ ಸನ್ನಿಧಿಯಿಂದ ಬಸದಿಗಳ ಶಿಲ್ಪಕಲೆಯವರೆಗೆ — ನಮ್ಮ ಜೈನ ಪರಂಪರೆಯನ್ನು ಹತ್ತಿರದಿಂದ ಪರಿಚಯಿಸಿಕೊಳ್ಳೋಣ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-09','2026-09-13T06:30:00Z','ಶ್ರವಣಬೆಳಗೊಳ','/images/hill.webp',null,null,'none',false,false,false,null,810,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','ef0cd62b-fb5a-467e-8172-78f87985104a') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001011','seed-moodbidri-basadi-archive','ಮೂಡುಬಿದಿರೆಯ ಸಾವಿರ ಕಂಬದ ಬಸದಿಯ ಕಲಾ ವೈಭವ','Moodbidri thousand pillar basadi','moodbidri basadi heritage','ಶತಮಾನಗಳ ಶಿಲ್ಪಕಲೆ, ಸಾಂಸ್ಕೃತಿಕ ಸ್ಮೃತಿ ಮತ್ತು ಜೈನ ಪರಂಪರೆಯ ಸುಂದರ ಪರಿಚಯ.','<p>ಶತಮಾನಗಳ ಶಿಲ್ಪಕಲೆ, ಸಾಂಸ್ಕೃತಿಕ ಸ್ಮೃತಿ ಮತ್ತು ಜೈನ ಪರಂಪರೆಯ ಸುಂದರ ಪರಿಚಯ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-09','2026-09-13T06:30:00Z','ಮೂಡುಬಿದಿರೆ','/images/temple.webp',null,null,'none',false,false,false,null,771,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','3fcfc94f-1294-4d73-8472-0b246ef587c8') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001012','seed-chaturmasa-reflections-archive','ಚಾತುರ್ಮಾಸ: ಆತ್ಮಚಿಂತನೆ ಮತ್ತು ಅಹಿಂಸೆಯ ಹಾದಿಯಲ್ಲಿ','Chaturmasa reflections on ahimsa','chaturmasa ahimsa pravachana','ನಿತ್ಯ ಜೀವನದಲ್ಲಿ ಸಂಯಮ, ಕರುಣೆ ಮತ್ತು ಸರಳತೆಯ ಮಹತ್ವವನ್ನು ತಿಳಿಸುವ ಚಿಂತನೆಗಳು.','<p>ನಿತ್ಯ ಜೀವನದಲ್ಲಿ ಸಂಯಮ, ಕರುಣೆ ಮತ್ತು ಸರಳತೆಯ ಮಹತ್ವವನ್ನು ತಿಳಿಸುವ ಚಿಂತನೆಗಳು.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','video','published','2026-09-08','2026-09-12T06:30:00Z','ಹಾಸನ','/images/detail.webp',null,null,'none',false,false,false,null,732,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','384ca3a5-2312-4d39-871b-09e69a7bc51b') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001013','seed-youth-community-archive','ಸಮಾಜದ ಸೇವೆಯಲ್ಲಿ ಯುವಜನರ ಪಾತ್ರ: ಹೊಸ ಹೆಜ್ಜೆಗಳು','Youth and community service','samaja youth community seva','ಶಿಕ್ಷಣ, ಪರಿಸರ ಮತ್ತು ಸಮಾಜಸೇವೆಯಲ್ಲಿ ಯುವಜನರ ಭಾಗವಹಿಸುವಿಕೆಗೆ ಒಂದು ವೇದಿಕೆ.','<p>ಶಿಕ್ಷಣ, ಪರಿಸರ ಮತ್ತು ಸಮಾಜಸೇವೆಯಲ್ಲಿ ಯುವಜನರ ಭಾಗವಹಿಸುವಿಕೆಗೆ ಒಂದು ವೇದಿಕೆ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-08','2026-09-12T06:30:00Z','ಬೆಂಗಳೂರು','/images/landscape.webp',null,null,'none',false,false,false,null,693,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','7cf4f1d9-b7ae-44d1-8eef-13c09299c523') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001014','seed-panchakalyana-tradition-archive','ಪಂಚಕಲ್ಯಾಣ ಮಹೋತ್ಸವದ ಆಚರಣೆಗಳು ಮತ್ತು ಮಹತ್ವ','Understanding Panchakalyana','panchakalyana utsava tradition','ಪಂಚಕಲ್ಯಾಣದ ಐದು ಮಂಗಳ ಸಂದರ್ಭಗಳ ಅರ್ಥ ಮತ್ತು ಅವು ನೀಡುವ ಜೀವನ ಸಂದೇಶ.','<p>ಪಂಚಕಲ್ಯಾಣದ ಐದು ಮಂಗಳ ಸಂದರ್ಭಗಳ ಅರ್ಥ ಮತ್ತು ಅವು ನೀಡುವ ಜೀವನ ಸಂದೇಶ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','video','published','2026-09-07','2026-09-12T06:30:00Z','ಮೈಸೂರು','/images/temple.webp',null,null,'none',false,false,false,null,654,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','a076bcef-aece-4905-8ba0-8c9935802acc') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001015','seed-jain-education-archive','ವಿದ್ಯೆಯ ಬೆಳಕು: ವಿದ್ಯಾರ್ಥಿಗಳ ಸಾಧನೆಗೆ ಸಮಾಜದ ಬೆಂಬಲ','Education and community support','education vidya students samaja','ಸಮುದಾಯದ ಸಹಕಾರದಿಂದ ಕಲಿಕೆಯ ಅವಕಾಶಗಳನ್ನು ವಿಸ್ತರಿಸುವ ವಿಚಾರಗಳ ಪರಿಚಯ.','<p>ಸಮುದಾಯದ ಸಹಕಾರದಿಂದ ಕಲಿಕೆಯ ಅವಕಾಶಗಳನ್ನು ವಿಸ್ತರಿಸುವ ವಿಚಾರಗಳ ಪರಿಚಯ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-07','2026-09-11T06:30:00Z','ತುಮಕೂರು','/images/detail.webp',null,null,'none',false,false,false,null,615,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','55fa6667-333a-4301-83db-0d49a930a3b3') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001016','seed-dharmasthala-journey-archive','ಧರ್ಮಸ್ಥಳದತ್ತ ಒಂದು ಸಾಂಸ್ಕೃತಿಕ ಪಯಣ','A cultural journey to Dharmasthala','dharmasthala heritage journey','ನಂಬಿಕೆ, ಸೇವೆ ಮತ್ತು ಸಹಬಾಳ್ವೆಯ ಪರಂಪರೆಯನ್ನು ಅರಿಯುವ ಒಂದು ಪಯಣ.','<p>ನಂಬಿಕೆ, ಸೇವೆ ಮತ್ತು ಸಹಬಾಳ್ವೆಯ ಪರಂಪರೆಯನ್ನು ಅರಿಯುವ ಒಂದು ಪಯಣ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','video','published','2026-09-06','2026-09-11T06:30:00Z','ಧರ್ಮಸ್ಥಳ','/images/landscape.webp',null,null,'none',false,false,false,null,576,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','0c83bae0-2a21-42be-869c-0a49154d43c1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001017','seed-ahimsa-daily-archive','ದಿನನಿತ್ಯದ ಬದುಕಿನಲ್ಲಿ ಅಹಿಂಸೆ: ಸಣ್ಣ ಬದಲಾವಣೆ, ದೊಡ್ಡ ಅರ್ಥ','Ahimsa in everyday life','ahimsa jain pravachana','ಮಾತು, ಮನಸ್ಸು ಮತ್ತು ನಡೆಗಳಲ್ಲಿ ಕರುಣೆಯ ದಾರಿಯನ್ನು ಅನುಸರಿಸುವ ಸರಳ ಮಾರ್ಗಗಳು.','<p>ಮಾತು, ಮನಸ್ಸು ಮತ್ತು ನಡೆಗಳಲ್ಲಿ ಕರುಣೆಯ ದಾರಿಯನ್ನು ಅನುಸರಿಸುವ ಸರಳ ಮಾರ್ಗಗಳು.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-06','2026-09-11T06:30:00Z','ಶ್ರವಣಬೆಳಗೊಳ','/images/hill.webp',null,null,'none',false,false,false,null,537,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','ef0cd62b-fb5a-467e-8172-78f87985104a') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001018','seed-basadi-conservation-archive','ನಮ್ಮ ಬಸದಿಗಳ ಸಂರಕ್ಷಣೆ: ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಪರಂಪರೆ','Preserving our basadis','basadi preservation heritage','ಐತಿಹಾಸಿಕ ಸ್ಮಾರಕಗಳ ಸಂರಕ್ಷಣೆಯಲ್ಲಿ ಸ್ಥಳೀಯ ಸಮುದಾಯದ ಜವಾಬ್ದಾರಿ.','<p>ಐತಿಹಾಸಿಕ ಸ್ಮಾರಕಗಳ ಸಂರಕ್ಷಣೆಯಲ್ಲಿ ಸ್ಥಳೀಯ ಸಮುದಾಯದ ಜವಾಬ್ದಾರಿ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','article','published','2026-09-05','2026-09-10T06:30:00Z','ಕಾರ್ಕಳ','/images/temple.webp',null,null,'none',false,false,false,null,498,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','bf02b30e-005a-4014-8d7c-e1315afc0e4d') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,type,status,event_date,published_at,event_place,thumbnail_url,video_url,video_id,video_provider,is_featured,is_breaking,is_live,duration_seconds,view_count,is_seed,image_credit,place_id) VALUES('00000000-0000-4000-8000-000000001019','seed-festival-community-archive','ಉತ್ಸವಗಳು ಬೆಸೆಯುವ ಸಮುದಾಯದ ಬಾಂಧವ್ಯ','Festivals bring us together','utsava samaja community festival','ಸಂಪ್ರದಾಯ ಮತ್ತು ಒಗ್ಗಟ್ಟಿನ ಆಚರಣೆಗಳ ಮೂಲಕ ಸಮುದಾಯದಲ್ಲಿ ಮೂಡುವ ಆತ್ಮೀಯತೆ.','<p>ಸಂಪ್ರದಾಯ ಮತ್ತು ಒಗ್ಗಟ್ಟಿನ ಆಚರಣೆಗಳ ಮೂಲಕ ಸಮುದಾಯದಲ್ಲಿ ಮೂಡುವ ಆತ್ಮೀಯತೆ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','video','published','2026-09-05','2026-09-10T06:30:00Z','ಬೆಳಗಾವಿ','/images/detail.webp',null,null,'none',false,false,false,null,459,true,'ಮಾದರಿ ಚಿತ್ರ — docs/ASSETS.md','8e420b12-4b76-4403-8ee5-6991a8cbeb74') ON CONFLICT (id) DO NOTHING;
