INSERT INTO public.quizzes(id,slug,title_kn,questions,status,is_seed) VALUES('2dc86f6a-cae5-4be5-8835-06c7ae735d45','reading-demo','ಓದುವ ಅನುಭವ — ಮಾದರಿ ರಸಪ್ರಶ್ನೆ','[{"question":"ಸುದ್ದಿಯನ್ನು ನಂತರ ಓದಲು ಯಾವ ಆಯ್ಕೆ ಬಳಸಬೇಕು?","options":["ಉಳಿಸಿ","ಹುಡುಕಿ","ಹಂಚಿಕೊಳ್ಳಿ"],"answer":0,"explanation":"ಉಳಿಸಿ ಆಯ್ಕೆ ಲೇಖನವನ್ನು ಮತ್ತೆ ತೆರೆಯಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ."},{"question":"ಕಾರ್ಯಕ್ರಮಕ್ಕೆ ಹೋಗುವ ಮೊದಲು ಏನು ದೃಢಪಡಿಸಬೇಕು?","options":["ಚಿತ್ರದ ಬಣ್ಣ","ದಿನಾಂಕ ಮತ್ತು ಸ್ಥಳ","ಪುಟದ ಗಾತ್ರ"],"answer":1,"explanation":"ದಿನಾಂಕ ಮತ್ತು ಸ್ಥಳವನ್ನು ಆಯೋಜಕರಿಂದ ದೃಢಪಡಿಸಿಕೊಳ್ಳಿ."}]','published',true) ON CONFLICT (id) DO NOTHING;
